insert into public.ppg_skill_domains
  (domain, label_th, label_en)
values
  ('Presentation Software', 'โปรแกรมนำเสนอ', 'Presentation Software'),
  ('Text and Layout', 'ข้อความและเลย์เอาต์', 'Text and Layout')
insert into public.ppg_modules
  (module_key, course_key, order_index, skill_domain, title_th, title_en, summary_th, summary_en, publication_state)
values
  ('chapter-03', 'presentation-program', 3, 'Presentation Software', 'การใช้โปรแกรมนำเสนอ', 'Using a presentation program', 'โปรแกรมนำเสนอ หน้าต่าง PowerPoint มุมมอง เค้าโครงสไลด์ และสไลด์ต้นแบบ', 'Presentation programs, the PowerPoint window and views, slide layouts, and the Slide Master.', 'published'),
  ('chapter-04', 'presentation-program', 4, 'Text and Layout', 'ข้อความบนสไลด์', 'Text on slides', 'จัดการและตกแต่งสไลด์ เน้นข้อความ สัญลักษณ์แสดงหัวข้อและการจัดลำดับเลข และจัดวางข้อความกับกล่องข้อความ', 'Managing and decorating slides, emphasising text, bullets and numbering, and arranging text with text boxes.', 'published')
insert into public.ppg_lessons
  (lesson_key, module_key, order_index, title_th, title_en, what_learn_th, what_learn_en, why_th, why_en, body_th, body_en, what_next_th, what_next_en, publication_state)
values
  ('chapter-03-lesson-01', 'chapter-03', 1, 'โปรแกรมนำเสนอและหน้าต่าง PowerPoint', 'Presentation programs and the PowerPoint window', 'บอกโปรแกรมนำเสนอที่ใช้บ่อย และองค์ประกอบของหน้าต่าง PowerPoint', 'Name common presentation programs and the parts of the PowerPoint window.', 'รู้จักเครื่องมือก่อนจึงใช้เครื่องมือถูกต้อง', 'You need to know the tools before you can use them with purpose.', 'โปรแกรมนำเสนอที่ใช้บ่อยคือ PowerPoint, Google Slides, LibreOffice Impress, Keynote และ Canva ทุกโปรแกรมทำงานคล้ายกัน หน้าต่าง PowerPoint มีริบบอนด้านบนบานสไลด์ด้านซ้ายพื้นที่แก้ไขกึ่งกลางและบานบันทึกด้านล่าง มุมมองที่ใช้บ่อยคือ Normal, Slide Sorter, Notes Page และ Slide Show', 'Common presentation programs are PowerPoint, Google Slides, LibreOffice Impress, Keynote, and Canva. They work on the same principles. The PowerPoint window has the ribbon at the top, the slide pane on the left, the editing area in the middle, and the notes pane at the bottom. The views you use most are Normal, Slide Sorter, Notes Page, and Slide Show.', 'ต่อไป: เค้าโครงสไลด์และการสร้างงานนำเสนอ', 'Next: slide layouts and creating a presentation.', 'published'),
  ('chapter-03-lesson-02', 'chapter-03', 2, 'เค้าโครงสไลด์เพลซโฮลเดอร์และการสร้างงานนำเสนอ', 'Slide layouts, placeholders, and creating a presentation', 'เลือกเค้าโครงสไลด์และเพลซโฮลเดอร์ให้พอดีกับเนื้อหาและสร้างงานนำเสนอได้', 'Choose a slide layout and placeholders that fit the content, and create a presentation.', 'เค้าโครงสไลด์เหมาะสมช่วยจัดวางเนื้อหาเร็วและอ่านง่าย', 'The right layout makes content quicker to place and easier to read.', 'เค้าโครงสไลด์คือรูปแบบจัดวางเพลซโฮลเดอร์ล่วงหน้า เพลซโฮลเดอร์คือกล่องสำหรับวางข้อความหรือวัตถุที่จัดรูปแบบไว้ สร้างงานนำเสนอเริ่มจากเลือกเทมเพลตหรือไฟล์ว่าง จากนั้นเพิ่ม New Slide และเลือกเลย์เอาต์ที่ต้องการ', 'A slide layout is a pre-arranged set of placeholders. A placeholder is a box for text or objects that is already formatted. To create a presentation, start from a template or a blank file, then add a new slide and choose the layout you need.', 'ต่อไป: สไลด์ต้นแบบและเทมเพลต', 'Next: the Slide Master and templates.', 'published'),
  ('chapter-03-lesson-03', 'chapter-03', 3, 'สไลด์ต้นแบบและเทมเพลต', 'The Slide Master and templates', 'ใช้สไลด์ต้นแบบและเทมเพลตทำให้ทั้งชุดมีรูปแบบเดียวกัน', 'Use the Slide Master and templates to keep the whole deck consistent.', 'แก้ไขที่ต้นแบบครั้งเดียวทุกสไลด์เปลี่ยนตาม', 'Edit the master once and every slide follows.', 'สไลด์ต้นแบบคือสไลด์แม่ที่ควบคุมแบบอักษร สี ตำแหน่งเพลซโฮลเดอร์และโลโก้ของทุกสไลด์ เทมเพลตคือชุดต้นแบบพร้อมนำไปใช้ทันทีทั้งสองช่วยทำให้การนำเสนอมีเอกลักษณ์เดียวกันและประหยัดเวลา', 'The Slide Master is the parent slide that controls fonts, colours, placeholder positions, and the logo for every slide. A template is a ready-made master set you can apply at once. Both keep a deck consistent and save time.', 'ต่อไป: ภารกิจและข้อสอบหลังเรียน', 'Next: the Knowledge Mission and the chapter post-test.', 'published'),
  ('chapter-04-lesson-01', 'chapter-04', 1, 'จัดการและตกแต่งสไลด์', 'Managing and decorating slides', 'เพิ่มทำซ้ำย้ายซ่อนและตกแต่งสไลด์ให้พอดีกับลำดับเรื่อง', 'Add, duplicate, move, hide, and decorate slides to fit the story order.', 'ลำดับสไลด์ที่ชัดเจนทำให้ผู้ฟังตามเรื่องได้ง่าย', 'A clear slide order makes the story easy to follow.', 'จัดการสไลด์หมายถึงเพิ่มทำซ้ำย้ายลบและซ่อนสไลด์ตามลำดับเรื่อง ตกแต่งสไลด์คือปรับพื้นหลังและสีให้อ่านง่ายและสอดคล้องกับเนื้อหา', 'Managing slides means adding, duplicating, moving, deleting, and hiding slides in story order. Decorating means adjusting the background and colour so the slide is easy to read and fits the content.', 'ต่อไป: เน้นข้อความสัญลักษณ์แสดงหัวข้อและการจัดลำดับเลข', 'Next: emphasising text, bullets, and numbering.', 'published'),
  ('chapter-04-lesson-02', 'chapter-04', 2, 'เน้นข้อความสัญลักษณ์แสดงหัวข้อและการจัดลำดับเลข', 'Emphasising text, bullets and numbering', 'ใช้ตัวหนาตัวเอียงสีและไฮไลต์พอดีและเลือกระหว่างสัญลักษณ์แสดงหัวข้อกับการจัดลำดับเลข', 'Use bold, italic, colour, and highlight with care, and choose between bullets and numbering.', 'เน้นมากเกินไปทำให้ไม่มีอะไรเด่น', 'Too much emphasis leaves nothing standing out.', 'เน้นข้อความใช้เพื่อชี้จุดสำคัญเช่นตัวหนาตัวเอียงขีดเส้นใต้สีและไฮไลต์ ควรเน้นเพียงหนึ่งหรือสองจุดต่อสไลด์สัญลักษณ์แสดงหัวข้อเหมาะสมสำหรับรายการที่ลำดับไม่สำคัญ การจัดลำดับเลขเหมาะสมสำหรับขั้นตอนที่ต้องเรียงตามลำดับ', 'Emphasis draws the eye to a key point: bold, italic, underline, colour, and highlight. Use one or two per slide. Bullets suit items whose order does not matter; numbering suits steps that must be followed in order.', 'ต่อไป: จัดวางข้อความย่อหน้าและกล่องข้อความ', 'Next: arranging text and paragraphs, and text boxes.', 'published'),
  ('chapter-04-lesson-03', 'chapter-04', 3, 'จัดวางข้อความและย่อหน้ากล่องข้อความ', 'Arranging text and paragraphs, text boxes', 'จัดข้อความ ตั้งระยะห่างบรรทัดและใช้กล่องข้อความให้อ่านง่าย', 'Align text, set line spacing, and use text boxes so the slide is easy to read.', 'ข้อความที่จัดวางดีช่วยอ่านเร็วและไม่ล้นออกนอกกล่อง', 'Well-arranged text is quick to read and stays inside its box.', 'จัดวางข้อความหมายถึงจัดข้อความชิดซ้าย ชิดขวา กึ่งกลางหรือชิดขอบตั้งระยะห่างบรรทัดและระยะห่างก่อนและหลังย่อหน้าช่วยอ่านสบาย กล่องข้อความใช้เมื่อต้องวางข้อความในตำแหน่งที่เค้าโครงไม่มี', 'Arranging text means aligning it left, right, centre, or justified. Line spacing and space before and after paragraphs make it comfortable to read. A text box lets you place text where the layout has no placeholder.', 'ต่อไป: ภารกิจความรู้และข้อสอบหลังเรียน', 'Next: the Knowledge Mission and the chapter post-test.', 'published')
insert into public.ppg_lesson_steps
  (lesson_key, order_index, kind, body_th, body_en, check_prompt_th, check_prompt_en, check_answer_key, check_explanation_th, check_explanation_en)
values
  ('chapter-03-lesson-01', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะบอกโปรแกรมนำเสนอที่ใช้บ่อย และองค์ประกอบของหน้าต่างและมุมมองหลักได้', 'By the end you can name common presentation programs, the parts of the window, and the main views.', null, null, null, null, null),
  ('chapter-03-lesson-01', 2, 'explanation', 'โปรแกรมนำเสนอทุกโปรแกรมมีหลักการเดียวกันคือวางข้อความและภาพบนสไลด์จากนั้นนำเสนอทีละหน้า', 'Every presentation program works the same way: put text and images on slides, then present them page by page.', null, null, null, null, null),
  ('chapter-03-lesson-01', 3, 'example', 'ตัวอย่างงานขาย เปิดข้อเสนอใน PowerPoint ทีมออกแบบใช้ Canva ทำภาพเพราะทำงานด้วยกันได้ง่าย', 'Example: the sales team opens the proposal in PowerPoint, while the design team uses Canva for visuals because it is easy to collaborate.', null, null, null, null, null),
  ('chapter-03-lesson-01', 4, 'explanation', 'หน้าต่าง PowerPoint มีริบบอนด้านบนบานสไลด์ด้านซ้ายพื้นที่แก้ไขกึ่งกลางและบานบันทึกด้านล่างใช้มุมมองปกติเมื่อแก้ไขสไลด์ใช้มุมมอง Slide Sorter เมื่อเรียงลำดับและใช้มุมมอง Slide Show เมื่อนำเสนอจริง', 'The PowerPoint window has the ribbon at the top, the slide pane on the left, the editing area in the middle, and the notes pane at the bottom. Use Normal to edit, Slide Sorter to reorder, and Slide Show to present.', null, null, null, null, null),
  ('chapter-03-lesson-01', 5, 'check', '', '', 'เมื่อต้องการเรียงลำดับสไลด์ไหม่ควรใช้มุมมองใด', 'Which view should you use to reorder slides?', 'b', 'มุมมอง Slide Sorter แสดงสไลด์ทั้งหมดเป็นภาพเล็กจึงลากสลับตำแหน่งง่าย', 'Slide Sorter shows all slides as thumbnails, so you can drag them into a new order.'),
  ('chapter-03-lesson-01', 6, 'summary', 'รู้จักโปรแกรม หน้าต่างและมุมมองจากนั้นสามารถสร้างงานนำเสนอมั่นใจ', 'Know the programs, the window, and the views, and you can start building with confidence.', null, null, null, null, null),
  ('chapter-03-lesson-02', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะเลือกเค้าโครงสไลด์และเพลซโฮลเดอร์ให้พอดีกับเนื้อหาและสร้างงานนำเสนอได้', 'By the end you can choose a slide layout and placeholders that fit the content, and create a presentation.', null, null, null, null, null),
  ('chapter-03-lesson-02', 2, 'explanation', 'เพลซโฮลเดอร์บอกตำแหน่งของชื่อเรื่อง เนื้อหา และภาพล่วงหน้า คุณเพียงคลิกจากนั้นพิมพ์', 'Placeholders set where the title, content, and images go in advance. You just click and type.', null, null, null, null, null),
  ('chapter-03-lesson-02', 3, 'example', 'ตัวอย่างสไลด์เปรียบเทียบคู่แข่งใช้เลย์เอาต์สองคอลัมน์เพื่อใส่จุดแข็งและจุดอ่อนเปรียบเทียบด้วยกันทันที', 'Example: a competitor comparison slide uses the two-content layout so strengths and weaknesses sit side by side.', null, null, null, null, null),
  ('chapter-03-lesson-02', 4, 'explanation', 'ไปที่แท็บ Home เลือก New Slide จากนั้นเลือก Layout ถ้าต้องการเปลี่ยนเลย์เอาต์ของสไลด์เดิม เลือก Layout อีกครั้ง', 'Go to the Home tab, choose New Slide, then choose Layout. To change an existing slide, open Layout again.', null, null, null, null, null),
  ('chapter-03-lesson-02', 5, 'check', '', '', 'เพลซโฮลเดอร์คืออะไร', 'What is a placeholder?', 'b', 'เพลซโฮลเดอร์คือกล่องที่เค้าโครงสไลด์เตรียมตำแหน่งและรูปแบบไว้แล้ว คุณเพียงคลิกและพิมพ์', 'A placeholder is a box whose position and formatting come from the layout; you only click and type.'),
  ('chapter-03-lesson-02', 6, 'summary', 'เลือกเลย์เอาต์ให้พอดีกับเนื้อหาจากนั้นใช้เพลซโฮลเดอร์ช่วยจัดวางเร็วขึ้น', 'Match the layout to the content, and let placeholders make placement faster.', null, null, null, null, null),
  ('chapter-03-lesson-03', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะใช้สไลด์ต้นแบบและเทมเพลตทำให้ทั้งชุดมีรูปแบบเดียวกันได้', 'By the end you can use the Slide Master and templates to keep the whole deck consistent.', null, null, null, null, null),
  ('chapter-03-lesson-03', 2, 'explanation', 'สไลด์ต้นแบบควบคุมแบบอักษรสี และตำแหน่งเพลซโฮลเดอร์ของทุกสไลด์ถ้าแก้ไขที่ต้นแบบทุกสไลด์จะเปลี่ยนตาม', 'The Slide Master controls the fonts, colours, and placeholder positions of every slide. Edit the master and every slide follows.', null, null, null, null, null),
  ('chapter-03-lesson-03', 3, 'example', 'ตัวอย่างบริษัทมีโลโก้และสีตราสินค้าการตลาดจึงตั้งสไลด์ต้นแบบครั้งเดียวจากนั้นทุกข้อเสนอใช้รูปแบบเดียวกัน', 'Example: the company has a logo and brand colours, so marketing sets the Slide Master once and every sales proposal uses the same format.', null, null, null, null, null),
  ('chapter-03-lesson-03', 4, 'explanation', 'ไปที่แท็บ View เลือก Slide Master แก้ไขแบบอักษรหรือตำแหน่งจากนั้นเลือก Close Master View เมื่อเสร็จหาเทมเพลตจากไฟล์ > New หรือ Design > Themes', 'Go to the View tab, choose Slide Master, edit the font or position, then choose Close Master View when you finish. Find templates under File > New or Design > Themes.', null, null, null, null, null),
  ('chapter-03-lesson-03', 5, 'check', '', '', 'ถ้าต้องการทุกสไลด์ใช้แบบอักษรเดียวกันควรแก้ไขที่ไหน', 'To make every slide use the same font, where should you make the change?', 'b', 'สไลด์ต้นแบบคือแม่ของทุกสไลด์แก้ไขครั้งเดียวจึงมีผลกับทั้งชุด', 'The Slide Master is the parent of every slide, so one edit applies to the whole deck.'),
  ('chapter-03-lesson-03', 6, 'summary', 'ตั้งต้นแบบดีตั้งแต่แรกจากนั้นทั้งชุดจะมีรูปแบบเดียวกันโดยไม่แก้ซ้ำอีกครั้ง', 'Set the master well from the start, and the whole deck stays consistent without rework.', null, null, null, null, null),
  ('chapter-04-lesson-01', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะจัดการลำดับสไลด์และตกแต่งสไลด์ให้พอดีกับเรื่องได้', 'By the end you can manage slide order and decorate slides to fit the story.', null, null, null, null, null),
  ('chapter-04-lesson-01', 2, 'explanation', 'ก่อนตกแต่งจัดวางลำดับสไลด์ให้เรื่องต่อเนื่องก่อนเพราะลำดับสำคัญมากกว่าลูกเล่น', 'Before decorating, put the slides in a continuous story order; sequence matters more than decoration.', null, null, null, null, null),
  ('chapter-04-lesson-01', 3, 'example', 'ตัวอย่างข้อเสนอสลับให้ปัญหาของลูกค้าอยู่ก่อนวิธีแก้และซ่อนสไลด์ตัวเลขราคาจนถึงช่วงจบ', 'Example: the sales proposal puts the customer problem before the solution and hides the price slide until the end.', null, null, null, null, null),
  ('chapter-04-lesson-01', 4, 'explanation', 'เพิ่มหรือทำซ้ำสไลด์ที่แท็บ Home ลากสไลด์ในมุมมอง Slide Sorter เพื่อย้ายลำดับ คลิกขวาจากนั้นเลือก Hide Slide เพื่อซ่อนและใช้แท็บ Design ตั้งพื้นหลังหรือธีม', 'Add or duplicate slides on the Home tab, drag slides in Slide Sorter to move them, right-click a slide and choose Hide Slide to hide it, and use the Design tab to set the background or theme.', null, null, null, null, null),
  ('chapter-04-lesson-01', 5, 'check', '', '', 'ควรทำอะไรกับสไลด์ที่ไม่ต้องการแสดงแต่ต้องเก็บไว้', 'What should you do with a slide you do not want to show but still need to keep?', 'b', 'ซ่อนสไลด์ยังเก็บเนื้อหาไว้ใช้ภายหลังโดยไม่แสดงเมื่อนำเสนอ', 'Hiding a slide keeps the content for later without showing it during the presentation.'),
  ('chapter-04-lesson-01', 6, 'summary', 'จัดวางเรื่องแรกจากนั้นตกแต่งและซ่อนสไลด์ที่ไม่ใช้', 'Order the story first, decorate second, and hide slides you do not need yet.', null, null, null, null, null),
  ('chapter-04-lesson-02', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะเน้นข้อความและเลือกระหว่างสัญลักษณ์แสดงหัวข้อกับการจัดลำดับเลขได้', 'By the end you can emphasise text and choose between bullets and numbering.', null, null, null, null, null),
  ('chapter-04-lesson-02', 2, 'explanation', 'การเน้นควรมีเหตุผลเช่นชี้ตัวเลขที่ต้องตัดสินใจไม่ใช่เน้นทุกคำ', 'Emphasis should have a reason, such as pointing to the number that needs a decision; it is not for every word.', null, null, null, null, null),
  ('chapter-04-lesson-02', 3, 'example', 'ตัวอย่างสไลด์รายงานความก้าวหน้าเน้นยอดขายที่ถึงเป้าเพียงจุดเดียวที่เหลือใช้ข้อความปกติ', 'Example: the progress report emphasises only the sales figure that reached target; the rest uses normal text.', null, null, null, null, null),
  ('chapter-04-lesson-02', 4, 'explanation', 'เลือกข้อความจากนั้นใช้แท็บ Home คลิก Bold Italic หรือ Underline เปลี่ยนสีที่ Font Color และเลือก Bullets หรือ Numbering ตามลักษณะรายการ', 'Select the text, use the Home tab to click Bold, Italic, or Underline, change the colour at Font Color, and choose Bullets or Numbering to match the list.', null, null, null, null, null),
  ('chapter-04-lesson-02', 5, 'check', '', '', 'รายการขั้นตอนที่ต้องทำตามลำดับควรใช้แบบใด', 'Which should you use for steps that must be followed in order?', 'b', 'การจัดลำดับเลขบอกผู้ฟังว่าขั้นตอนข้อใดก่อนหลังขณะที่สัญลักษณ์แสดงหัวข้อไม่บอก', 'Numbering shows which step comes before or after; bullets do not.'),
  ('chapter-04-lesson-02', 6, 'summary', 'เน้นน้อยแต่ตรงจุดและเลือกรูปแบบรายการให้พอดีกับความหมาย', 'Emphasise little but precisely, and match the list style to the meaning.', null, null, null, null, null),
  ('chapter-04-lesson-03', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะจัดข้อความตั้งระยะห่างและใช้กล่องข้อความได้', 'By the end you can align text, set spacing, and use a text box.', null, null, null, null, null),
  ('chapter-04-lesson-03', 2, 'explanation', 'จัดข้อความให้แนวเดียวกันทั้งสไลด์ และตั้งระยะห่างบรรทัดให้อ่านสบาย', 'Align text to the same line across the slide and set line spacing so it is comfortable to read.', null, null, null, null, null),
  ('chapter-04-lesson-03', 3, 'example', 'ตัวอย่างสไลด์สรุปใช้หัวข้อชิดซ้ายเนื้อหาชิดซ้ายระยะห่างบรรทัด 1.5 เท่าและเพิ่มกล่องข้อความสำหรับหมายเหตุท้ายสไลด์', 'Example: the summary slide uses a left-aligned heading, left-aligned content, 1.5 line spacing, and a text box for a note at the bottom.', null, null, null, null, null),
  ('chapter-04-lesson-03', 4, 'explanation', 'เลือกข้อความจากนั้นใช้แท็บ Home ปรับ Align Left Center หรือ Align Right ตั้ง Line Spacing ที่ Line Spacing และ Insert Text Box ไหม่ที่ Insert > Text Box', 'Select the text, use the Home tab to set Align Left, Center, or Align Right, set Line Spacing at Line Spacing, and insert a new text box at Insert > Text Box.', null, null, null, null, null),
  ('chapter-04-lesson-03', 5, 'check', '', '', 'ถ้าข้อความยาวเกินกล่องจนล้นออกนอกกล่องควรทำอย่างไร', 'If text overflows its box, what should you do?', 'b', 'ข้อความที่ล้นออกนอกกล่องอ่านไม่ครบควรลดขนาดหรือแบ่งเนื้อหาให้พอดีกับกล่อง', 'Overflowing text is not fully readable; reduce the size or split the content to fit the box.'),
  ('chapter-04-lesson-03', 6, 'summary', 'จัดแนวเดียวกันตั้งระยะห่างพอดีและใช้กล่องข้อความเมื่อต้องการตำแหน่งอิสระ', 'Align consistently, set comfortable spacing, and use a text box when you need free placement.', null, null, null, null, null)
