  ('chapter-03-lesson-03', 5, 'c', 'แก้ไขที่บานบันทึก', 'Edit the notes pane'),
  ('chapter-04-lesson-01', 5, 'a', 'ลบสไลด์ทิ้ง', 'Delete the slide for good'),
  ('chapter-04-lesson-01', 5, 'b', 'ซ่อนสไลด์', 'Hide the slide'),
  ('chapter-04-lesson-01', 5, 'c', 'ย้ายไปไว้ท้ายสุด', 'Move it to the very end'),
  ('chapter-04-lesson-02', 5, 'a', 'สัญลักษณ์แสดงหัวข้อ', 'Bullets'),
  ('chapter-04-lesson-02', 5, 'b', 'การจัดลำดับเลข', 'Numbering'),
  ('chapter-04-lesson-02', 5, 'c', 'ไม่ต้องมีรายการ', 'No list at all'),
  ('chapter-04-lesson-03', 5, 'a', 'เพิ่มขนาดตัวอักษร', 'Increase the font size'),
  ('chapter-04-lesson-03', 5, 'b', 'ลดขนาดตัวอักษรหรือแบ่งเป็นสองกล่อง', 'Reduce the font size or split it into two boxes'),
  ('chapter-04-lesson-03', 5, 'c', 'ปล่อยให้ล้นออกนอกสไลด์', 'Let it overflow off the slide')
insert into public.ppg_knowledge_missions
  (module_key, instructions_th, instructions_en)
values
  ('chapter-03', 'ภารกิจความรู้:ตอบคำถามหกข้อเกี่ยวกับโปรแกรมนำเสนอผ่านที่ 70%และทำซ้ำได้ไม่จำกัด', 'Knowledge Mission: answer six questions about presentation programs. 70% passes; you can retry without limit.'),
  ('chapter-04', 'ภารกิจความรู้:ตอบคำถามหกข้อเกี่ยวกับข้อความและตกแต่งสไลด์ผ่านที่ 70%และทำซ้ำได้ไม่จำกัด', 'Knowledge Mission: answer six questions about text and slide management. 70% passes; you can retry without limit.')
insert into public.ppg_knowledge_mission_questions
  (module_key, order_index, option_key, prompt_th, prompt_en, option_th, option_en, is_correct, explanation_th, explanation_en, review_th, review_en)
values
  ('chapter-03', 1, 'a', 'ข้อใดเป็นโปรแกรมนำเสนอ', 'Which of these is a presentation program?', 'PowerPoint', 'PowerPoint', true, 'PowerPoint เป็นโปรแกรมนำเสนอส่วนโปรแกรมตารางและโปรแกรมตัดต่อวิดีโอทำงานต่างกัน', 'PowerPoint is a presentation program; a spreadsheet or video editor works differently.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 1, 'b', 'ข้อใดเป็นโปรแกรมนำเสนอ', 'Which of these is a presentation program?', 'โปรแกรมตาราง', 'A spreadsheet program', false, 'PowerPoint เป็นโปรแกรมนำเสนอส่วนโปรแกรมตารางและโปรแกรมตัดต่อวิดีโอทำงานต่างกัน', 'PowerPoint is a presentation program; a spreadsheet or video editor works differently.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 1, 'c', 'ข้อใดเป็นโปรแกรมนำเสนอ', 'Which of these is a presentation program?', 'โปรแกรมตัดต่อวิดีโอ', 'A video editor', false, 'PowerPoint เป็นโปรแกรมนำเสนอส่วนโปรแกรมตารางและโปรแกรมตัดต่อวิดีโอทำงานต่างกัน', 'PowerPoint is a presentation program; a spreadsheet or video editor works differently.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 2, 'a', 'โปรแกรมใดทำงานเทียบเท่า PowerPoint', 'Which program is equivalent to PowerPoint?', 'Google Slides', 'Google Slides', true, 'Google Slides LibreOffice Impress Keynote และ Canva เป็นโปรแกรมนำเสนอที่ทำงานคล้ายกัน PowerPoint', 'Google Slides, LibreOffice Impress, Keynote, and Canva are presentation programs that work like PowerPoint.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 2, 'b', 'โปรแกรมใดทำงานเทียบเท่า PowerPoint', 'Which program is equivalent to PowerPoint?', 'โปรแกรมบัญชี', 'An accounting program', false, 'Google Slides LibreOffice Impress Keynote และ Canva เป็นโปรแกรมนำเสนอที่ทำงานคล้ายกัน PowerPoint', 'Google Slides, LibreOffice Impress, Keynote, and Canva are presentation programs that work like PowerPoint.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 2, 'c', 'โปรแกรมใดทำงานเทียบเท่า PowerPoint', 'Which program is equivalent to PowerPoint?', 'โปรแกรมตาราง', 'A spreadsheet program', false, 'Google Slides LibreOffice Impress Keynote และ Canva เป็นโปรแกรมนำเสนอที่ทำงานคล้ายกัน PowerPoint', 'Google Slides, LibreOffice Impress, Keynote, and Canva are presentation programs that work like PowerPoint.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 3, 'a', 'ส่วนใดของหน้าต่าง PowerPoint ใช้เลือกคำสั่ง', 'Which part of the PowerPoint window is used to choose commands?', 'ริบบอน', 'The ribbon', true, 'ริบบอนเป็นส่วนที่มีคำสั่งและเครื่องมือสำหรับงาน', 'The ribbon holds the commands and tools for the work.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 3, 'b', 'ส่วนใดของหน้าต่าง PowerPoint ใช้เลือกคำสั่ง', 'Which part of the PowerPoint window is used to choose commands?', 'บานบันทึก', 'The notes pane', false, 'ริบบอนเป็นส่วนที่มีคำสั่งและเครื่องมือสำหรับงาน', 'The ribbon holds the commands and tools for the work.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 3, 'c', 'ส่วนใดของหน้าต่าง PowerPoint ใช้เลือกคำสั่ง', 'Which part of the PowerPoint window is used to choose commands?', 'แถบสถานะ', 'The status bar', false, 'ริบบอนเป็นส่วนที่มีคำสั่งและเครื่องมือสำหรับงาน', 'The ribbon holds the commands and tools for the work.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 4, 'a', 'มุมมองใดเหมาะสมสำหรับนำเสนอจริง', 'Which view suits presenting to an audience?', 'มุมมองปกติ', 'The Normal view', false, 'มุมมองการนำเสนอแสดงสไลด์เต็มจอสำหรับผู้ฟัง', 'Slide Show shows the slides full screen for the audience.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 4, 'b', 'มุมมองใดเหมาะสมสำหรับนำเสนอจริง', 'Which view suits presenting to an audience?', 'มุมมองตัวเรียงสไลด์', 'The Slide Sorter view', false, 'มุมมองการนำเสนอแสดงสไลด์เต็มจอสำหรับผู้ฟัง', 'Slide Show shows the slides full screen for the audience.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 4, 'c', 'มุมมองใดเหมาะสมสำหรับนำเสนอจริง', 'Which view suits presenting to an audience?', 'มุมมองการนำเสนอ', 'The Slide Show view', true, 'มุมมองการนำเสนอแสดงสไลด์เต็มจอสำหรับผู้ฟัง', 'Slide Show shows the slides full screen for the audience.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-03', 5, 'a', 'เพลซโฮลเดอร์มีประโยชน์อย่างไร', 'What does a placeholder help with?', 'ตั้งตำแหน่งและรูปแบบสำหรับใส่เนื้อหาเร็ว', 'It sets position and format so content goes in quickly', true, 'เพลซโฮลเดอร์ทำให้ใส่เนื้อหาเร็วเพราะรูปแบบพร้อมไว้แล้ว', 'Placeholders speed up content entry because their formatting is already set.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-03', 5, 'b', 'เพลซโฮลเดอร์มีประโยชน์อย่างไร', 'What does a placeholder help with?', 'เพิ่มตัวเลขสไลด์อัตโนมัติ', 'It adds slides automatically', false, 'เพลซโฮลเดอร์ทำให้ใส่เนื้อหาเร็วเพราะรูปแบบพร้อมไว้แล้ว', 'Placeholders speed up content entry because their formatting is already set.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-03', 5, 'c', 'เพลซโฮลเดอร์มีประโยชน์อย่างไร', 'What does a placeholder help with?', 'เปลี่ยนสีพื้นหลังทั้งชุด', 'It changes the whole deck background', false, 'เพลซโฮลเดอร์ทำให้ใส่เนื้อหาเร็วเพราะรูปแบบพร้อมไว้แล้ว', 'Placeholders speed up content entry because their formatting is already set.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-03', 6, 'a', 'สไลด์ต้นแบบมีผลกับอะไร', 'What does the Slide Master affect?', 'เฉพาะสไลด์แรก', 'Only the first slide', false, 'สไลด์ต้นแบบควบคุมแบบอักษร สี และตำแหน่งสำหรับทุกสไลด์', 'The Slide Master controls the font, colour, and position for every slide.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-03', 6, 'b', 'สไลด์ต้นแบบมีผลกับอะไร', 'What does the Slide Master affect?', 'ทุกสไลด์ในการนำเสนอ', 'Every slide in the presentation', true, 'สไลด์ต้นแบบควบคุมแบบอักษร สี และตำแหน่งสำหรับทุกสไลด์', 'The Slide Master controls the font, colour, and position for every slide.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-03', 6, 'c', 'สไลด์ต้นแบบมีผลกับอะไร', 'What does the Slide Master affect?', 'เฉพาะสไลด์ที่เลือก', 'Only the slide you select', false, 'สไลด์ต้นแบบควบคุมแบบอักษร สี และตำแหน่งสำหรับทุกสไลด์', 'The Slide Master controls the font, colour, and position for every slide.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-04', 1, 'a', 'ถ้าต้องการย้ายสไลด์ไปไว้ต้นเรื่องควรทำอย่างไร', 'How should you move a slide to the start of the story?', 'ลบจากนั้นสร้างไหม่', 'Delete it and create a new one', false, 'ลากสไลด์ในมุมมอง Slide Sorter เปลี่ยนลำดับได้ง่าย', 'Dragging in Slide Sorter changes the order easily.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-04', 1, 'b', 'ถ้าต้องการย้ายสไลด์ไปไว้ต้นเรื่องควรทำอย่างไร', 'How should you move a slide to the start of the story?', 'ลากสไลด์ในมุมมอง Slide Sorter', 'Drag the slide in Slide Sorter', true, 'ลากสไลด์ในมุมมอง Slide Sorter เปลี่ยนลำดับได้ง่าย', 'Dragging in Slide Sorter changes the order easily.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-04', 1, 'c', 'ถ้าต้องการย้ายสไลด์ไปไว้ต้นเรื่องควรทำอย่างไร', 'How should you move a slide to the start of the story?', 'ซ่อนสไลด์', 'Hide the slide', false, 'ลากสไลด์ในมุมมอง Slide Sorter เปลี่ยนลำดับได้ง่าย', 'Dragging in Slide Sorter changes the order easily.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-04', 2, 'a', 'ซ่อนสไลด์เหมาะสมกับสถานการณ์ข้อใด', 'When is hiding a slide the right choice?', 'สไลด์ที่ไม่ต้องแสดงแต่ต้องเก็บ', 'A slide you do not need to show but must keep', true, 'ซ่อนสไลด์เก็บเนื้อหาสำหรับใช้ภายหลังโดยไม่แสดงเมื่อนำเสนอ', 'Hiding keeps the content for later without showing it during the presentation.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-04', 2, 'b', 'ซ่อนสไลด์เหมาะสมกับสถานการณ์ข้อใด', 'When is hiding a slide the right choice?', 'สไลด์ที่ต้องการลบทิ้ง', 'A slide you want to delete for good', false, 'ซ่อนสไลด์เก็บเนื้อหาสำหรับใช้ภายหลังโดยไม่แสดงเมื่อนำเสนอ', 'Hiding keeps the content for later without showing it during the presentation.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-04', 2, 'c', 'ซ่อนสไลด์เหมาะสมกับสถานการณ์ข้อใด', 'When is hiding a slide the right choice?', 'สไลด์ที่ต้องแสดงทุกครั้ง', 'A slide you show every time', false, 'ซ่อนสไลด์เก็บเนื้อหาสำหรับใช้ภายหลังโดยไม่แสดงเมื่อนำเสนอ', 'Hiding keeps the content for later without showing it during the presentation.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-04', 3, 'a', 'ตกแต่งสไลด์ที่ดีควรทำอะไร', 'What should good slide decoration do?', 'ใช้สีและพื้นหลังอ่านง่ายและสอดคล้องกับเนื้อหา', 'Use colour and background that are easy to read and fit the content', true, 'ตกแต่งดีช่วยอ่านง่ายไม่ใช่ใส่ทั้งหมด', 'Good decoration helps readability; it does not mean putting everything in.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-04', 3, 'b', 'ตกแต่งสไลด์ที่ดีควรทำอะไร', 'What should good slide decoration do?', 'ใส่สีหลายแบบทุกสไลด์', 'Use many colours on every slide', false, 'ตกแต่งดีช่วยอ่านง่ายไม่ใช่ใส่ทั้งหมด', 'Good decoration helps readability; it does not mean putting everything in.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-04', 3, 'c', 'ตกแต่งสไลด์ที่ดีควรทำอะไร', 'What should good slide decoration do?', 'ใช้ภาพทุกภาพที่มี', 'Use every picture you have', false, 'ตกแต่งดีช่วยอ่านง่ายไม่ใช่ใส่ทั้งหมด', 'Good decoration helps readability; it does not mean putting everything in.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
